css:
:root {
  --navy: #1b2360;
  --white: #ffffff;
  --ink: #212529;
  --muted: #5b5b5b;
  --ice: #eaf8ff;
  --line: #d9e4ec;
  --field: #6c757d;
  --teal: #64d2d3;
  --orange: #ff931e;
  --cta: #d66400;
  --cta-hover: #c25a00;
  --on-cta: #ffffff;
  --lean: #48aeee;
  --signature: #8cc63f;
  --performance: #f7941d;
  --family: #f5bb00;
  --radius: 6px;
  --head: Poppins, system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
  --body: "Open Sans", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
}
:root { --draft: #8a1c1c; }
@font-face { font-family: "Open Sans"; font-style: normal; font-weight: 400; font-display: swap; src: url("/fonts/open-sans-latin-400-normal.woff2") format("woff2"); }
@font-face { font-family: "Open Sans"; font-style: normal; font-weight: 600; font-display: swap; src: url("/fonts/open-sans-latin-600-normal.woff2") format("woff2"); }
@font-face { font-family: Poppins; font-style: normal; font-weight: 600; font-display: swap; src: url("/fonts/poppins-latin-600-normal.woff2") format("woff2"); }
@font-face { font-family: Poppins; font-style: normal; font-weight: 700; font-display: swap; src: url("/fonts/poppins-latin-700-normal.woff2") format("woff2"); }
* { box-sizing: border-box; }
body { margin: 0; background: var(--white); color: var(--ink); font: 400 16px/1.6 var(--body); }
.worker-page { max-width: 680px; margin: 0 auto; padding: 24px 16px 48px; }
.logo { display: block; width: 88px; margin: 0 0 20px; }
.logo img { display: block; width: 88px; height: 56px; }
h1 { margin: 0 0 16px; font: 700 30px/1.2 var(--head); color: var(--navy); }
p { margin: 0 0 14px; }
strong { font-weight: 600; color: var(--navy); }
a { color: var(--navy); font: 600 16px var(--head); text-decoration: underline; text-underline-offset: 3px; }
.action { margin: 24px 0 14px; }
.action a { display: flex; align-items: center; justify-content: center; min-height: 64px; padding: 14px 20px; border-radius: 4px; background: var(--cta); color: var(--on-cta); font: 700 19px/1.2 var(--head); letter-spacing: .03em; text-transform: uppercase; text-decoration: none; }
.action a:hover { background: var(--cta-hover); }
button { min-height: 48px; padding: 10px 18px; margin: 0 8px 8px 0; border: 1px solid var(--line); border-radius: 32px; background: var(--white); color: var(--navy); font: 600 16px var(--head); cursor: pointer; }
.draft { margin: 0 0 12px; font-size: 12px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: var(--draft); }
